s+="""
describe('ToolRegistry function-valued definition caching', () => {
  it('compiles each returned schema object once and enforces the schema current at each call', async () => {
    const compile = jest.spyOn(AjvModule.default.prototype, 'compile');
    const needsCity = {type: 'object', properties: {city: {type: 'string'}}, required: ['city']};
    const needsZip = {type: 'object', properties: {zip: {type: 'string'}}, required: ['zip']};
    const schemas = [needsCity, needsCity, needsZip];
    const registry = new ToolRegistry();
    registry.register(
      () => ({name: 'locate', description: 'Locate', inputSchema: schemas.shift() ?? needsZip}),
      async () => 'ok'
    );

    const results = [];
    for (const input of [{city: 'Oslo'}, {city: 'Oslo'}, {city: 'Oslo'}]) {
      results.push((await registry.execute('locate', input)).result);
    }

    expect({compiles: compile.mock.calls.length, results}).toEqual({
      compiles: 2,
      results: ['ok', 'ok', 'Invalid input for locate: zip is required'],
    });
    compile.mockRestore();
  });
});
"""
open(p,'w').write(s)
